/** 截图问题的真实浏览器回归：解码阅读、自动 Markdown/代码及收起的设置。 */
import assert from 'node:assert/strict';
import { mkdir, writeFile } from 'node:fs/promises';
export async function runPolish(page, artifactDir) {
  const checks=[];
  const check=(name,condition)=>{assert.ok(condition,name);checks.push(name);};
  const settle=()=>page.evaluate(()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve))));
  const select=async id=>{await page.selectOption('select[aria-label="Fixture"]',id);await settle();};
  const toggle=async(index,checked)=>{if(await page.evaluate(i=>document.querySelectorAll('#cx-reader-settings input')[i].checked,index)!==checked)await page.click(`#cx-reader-settings input >> nth=${index}`);};
  const expand=async()=>{if(await page.evaluate(()=>!document.querySelector('.cx-reader-expanded'))){await page.focus('.cx-reader-expand');await page.press('.cx-reader-expand','Enter');}await settle();};
  const shot=async name=>{const size=await page.evaluate(()=>({width:Math.ceil(innerWidth*devicePixelRatio),height:Math.ceil(innerHeight*devicePixelRatio)}));const r=await page.cdp('Page.captureScreenshot',{format:'png',captureBeyondViewport:true,clip:{x:0,y:0,...size,scale:1}});await writeFile(`${artifactDir}/${name}.png`,Buffer.from(r.data,'base64'));};
  await mkdir(artifactDir,{recursive:true});
  await page.reload();await page.click('text="English"');
  await page.evaluate(()=>{document.documentElement.dataset.theme='light';Object.defineProperty(navigator,'clipboard',{configurable:true,value:{writeText:async text=>{window.qaCopied=text;}}});});
  await select('markdown_output');await expand();
  check('Text transport automatically renders Markdown with table and highlighted fence',await page.evaluate(()=>!!document.querySelector('.cx-reader-rich h1')&&!!document.querySelector('.cx-reader-rich table')&&!!document.querySelector('.cx-reader-rich .hljs-keyword')));
  check('Markdown heading retains reading typography',await page.evaluate(()=>parseFloat(getComputedStyle(document.querySelector('.cx-reader-heading-toggle')).fontSize)>parseFloat(getComputedStyle(document.querySelector('.cx-reader-rich')).fontSize)));
  check('YAML frontmatter is preserved instead of hidden',await page.evaluate(()=>document.querySelector('[data-reader-frontmatter]')?.textContent.includes('reader-fixture')));
  check('Default body toolbar has no size, wrapping or line-number controls',await page.evaluate(()=>!document.querySelector('.cx-reader-toolbar')&&!document.querySelector('#cx-reader-settings')&&!!document.querySelector('[aria-label="Output format"]')));
  await page.evaluate(()=>document.querySelector('.cx-reader-rich').scrollIntoView({block:'start'}));await shot('06-auto-markdown-output');
  await page.click('.cx-reader-settings-trigger');await settle();
  check('Reading settings are keyboard reachable and focused',await page.evaluate(()=>document.activeElement===document.querySelector('#cx-reader-settings select')));
  await page.selectOption('#cx-reader-settings select','18');
  await toggle(0,false);
  await toggle(1,true);
  await shot('07-compact-reading-settings');
  await page.press('#cx-reader-settings select','Escape');
  check('Escape closes settings before leaving expanded reading',await page.evaluate(()=>!document.querySelector('#cx-reader-settings')&&!!document.querySelector('.cx-reader-expanded')&&document.activeElement===document.querySelector('.cx-reader-settings-trigger')));
  await select('auto_code');await expand();
  check('Unlabelled Python is automatically recognized and highlighted',await page.evaluate(()=>document.querySelector('.cx-reader-code-head')?.textContent.includes('python · detected')&&!!document.querySelector('.hljs-keyword')));
  check('Shared settings apply across entries',await page.evaluate(()=>getComputedStyle(document.querySelector('.cx-reader-pre')).fontSize==='16px'&&!document.querySelector('.cx-reader-pre').classList.contains('wrap')&&document.querySelector('.cx-reader-pre').classList.contains('numbered')));
  await page.click('.cx-reader-code-head button');
  check('Auto-highlight copy retains indentation without line numbers',await page.evaluate(()=>window.qaCopied==='def greet(name):\n    message = "Hello " + name\n    return message\n'));
  await page.selectOption('[aria-label="Output code language"]','text');
  check('Manual plain code disables automatic highlighting',await page.evaluate(()=>!document.querySelector('.hljs-keyword')));
  await select('escaped_output');await expand();
  await page.click('[aria-label="Expand content"]');await page.click('[aria-label="Expand 0"]');await page.click('[aria-label="Expand text"]');
  check('JSON text expands directly to decoded Markdown reading',await page.evaluate(()=>document.querySelector('.cx-reader-string-toolbar select').value==='auto'&&!!document.querySelector('.cx-reader-json-string h1')&&!!document.querySelector('.cx-reader-json-string table')));
  check('Truncation warning and source fragment remain visible',await page.evaluate(()=>document.querySelector('.cx-reader-json-string').textContent.includes('Warning: truncated output')&&document.querySelector('.cx-reader-integrity').textContent.includes('Source was truncated')));
  await page.selectOption('.cx-reader-string-toolbar select','text');
  check('Text body shows actual newlines and no JSON wrapper',await page.evaluate(()=>document.querySelector('.cx-reader-json-string pre').textContent===window.readerFixture.stringOutput));
  await page.click('loc=role:button[name="Copy string body"]');
  check('Decoded string copy is exact',await page.evaluate(()=>window.qaCopied===window.readerFixture.stringOutput));
  await page.click('loc=role:button[name="Copy JSON source"]');
  check('JSON source copy retains original quotes and escaped newlines',await page.evaluate(()=>window.qaCopied===JSON.stringify(window.readerFixture.stringOutput)&&window.qaCopied.includes('\\n')));
  await page.selectOption('.cx-reader-string-toolbar select','source');
  check('Original JSON remains explicitly available',await page.evaluate(()=>document.querySelector('.cx-reader-json-string pre').textContent===JSON.stringify(window.readerFixture.stringOutput)));
  await page.selectOption('.cx-reader-string-toolbar select','auto');
  await page.evaluate(()=>document.querySelector('.cx-reader-json-string').scrollIntoView({block:'start'}));await shot('08-decoded-json-markdown');
  await select('auto_code');await select('escaped_output');
  check('Decoded string view and folding persist after switching entries',await page.evaluate(()=>document.querySelector('.cx-reader-string-toolbar select').value==='auto'&&!!document.querySelector('.cx-reader-json-string h1')));
  await page.reload();await select('auto_code');await expand();
  check('Reading settings survive reload',await page.evaluate(()=>getComputedStyle(document.querySelector('.cx-reader-pre')).fontSize==='16px'&&document.querySelector('.cx-reader-pre').classList.contains('numbered')&&!document.querySelector('.cx-reader-pre').classList.contains('wrap')));
  await page.click('.cx-reader-settings-trigger');await page.selectOption('#cx-reader-settings select','15');await toggle(0,true);await toggle(1,false);await page.press('#cx-reader-settings select','Escape');
  await page.cdp('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true});
  await page.evaluate(()=>{window.readerFixture.setLanguage('zh');document.documentElement.dataset.theme='dark';});await settle();
  await page.focus('.cx-reader-settings-trigger');await page.press('.cx-reader-settings-trigger','Enter');await settle();
  check('Narrow Chinese dark settings fit inside the reader',await page.evaluate(()=>{const r=document.querySelector('#cx-reader-settings').getBoundingClientRect();return r.left>=0&&r.right<=innerWidth+1&&document.querySelector('#cx-reader-settings').textContent.includes('自动换行');}));
  await shot('09-narrow-settings');
  await page.press('#cx-reader-settings select','Escape');
  await page.cdp('Emulation.clearDeviceMetricsOverride');
  await writeFile(`${artifactDir}/polish-checks.json`,JSON.stringify(checks,null,2));
  return checks;
}
